$content = [System.IO.File]::ReadAllText("script.js", [System.Text.Encoding]::UTF8)

# SUBJECT_GRADE_MAP
$content = $content -replace "(?s)const SUBJECT_GRADE_MAP = \{.*?\};", "const SUBJECT_GRADE_MAP = { informatics: [1, 2, 3, 4] };"

# Badges B64 mapping
$badgesB64 = ""
$badgesText = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($badgesB64))
$content = $content -replace "(?s)const badges = \{.*?\};", $badgesText

# Subjects and labels B64 map
$subjectsB64 = "Y29uc3Qgc3ViamVjdHMgPSB7IGluZm9ybWF0aWNzOiAn0IbQvdGE0L7RgNC80LDRgtC40LrQsCcgfTs="
$subjectsB64Label = "Y29uc3QgYmFkZ2VTdWJqZWN0TGFiZWxzID0gewogICAgICAgICAgICBpbmZvcm1hdGljczogJ9CG0L3RhNC+0YDQvNCw0YLQuNC60LAnLAogICAgICAgICAgICB0b3RhbDogJ9Cj0YHQuCDQv9GA0LXQtNC80LXRgtC4JwogICAgICAgIH07"
$subjtxt = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($subjectsB64))
$subjLblTxt = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($subjectsB64Label))
$content = $content -replace "(?s)const subjects = \{ math:.*?english: '.*? \};", $subjtxt
$content = $content -replace "(?s)const badgeSubjectLabels = \{.*?total: '.*?'\r?\n\s+\};", $subjLblTxt

$titleB64 = "ZG9jdW1lbnQuZ2V0RWxlbWVudEJ5SWQoJ3Rlc3QtdGl0bGUnKS50ZXh0Q29udGVudCA9IHsgaW5mb3JtYXRpY3M6ICfQhtC90YTQvtGA0LzQsNGC0LjQutCwJyB9W3N1YmplY3RdIHx8ICfQhtC90YTQvtGA0LzQsNGC0LjQutCwJzs="
$titleTxt = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($titleB64))
$content = $content -replace "(?s)document\.getElementById\('test-title'\)\.textContent = \{ math: '.*?\}\[subject\];", $titleTxt

# Selectors logic
$selectorB64 = ""
$selectorText = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($selectorB64))

$content = $content -replace "(?s)function showGradeSelector\(subject, triggerButton\).*?showModal\(modal\);\r?\n}", $selectorText

$content = $content -replace "document\.querySelectorAll\('\.start-test-btn'\)\.forEach\(btn=>\{\r?\n.*?\}\);", ""

$content = $content -replace "(?s)document\.getElementById\('cancel-grade-selection-btn'\)\.addEventListener\('click', \(\) => \{\r?\n\s*hideModal\(document\.getElementById\('grade-selection-modal'\)\);\r?\n\s*\}\);", "initSelectors('welcome');`n  initSelectors('dashboard');"

[System.IO.File]::WriteAllText("script.js", $content, [System.Text.Encoding]::UTF8)
